<?php
namespace App\Http\Controllers\Api\Admin;use App\Http\Controllers\Controller;use App\Models\SupportTicket;use Illuminate\Http\Request;use App\Services\Notification\NotificationService;
class SupportTicketController extends Controller{public function index(Request $r){return SupportTicket::with('user:id,name,mobile')->withCount('messages')->when($r->status,fn($q,$v)=>$q->where('status',$v))->when($r->department,fn($q,$v)=>$q->where('department',$v))->latest('last_message_at')->paginate(20);}public function show(SupportTicket $ticket){$ticket->messages()->where('is_staff',false)->whereNull('read_at')->update(['read_at'=>now()]);return $ticket->load(['user:id,name,mobile','order:id,number','messages.user:id,name,avatar']);}public function reply(Request $r,SupportTicket $ticket,NotificationService $notifications){$data=$r->validate(['body'=>'required|string|min:2|max:5000','status'=>'sometimes|in:answered,pending,closed']);$message=$ticket->messages()->create(['user_id'=>$r->user()->id,'body'=>$data['body'],'is_staff'=>true]);$ticket->update(['status'=>$data['status']??'answered','last_message_at'=>now()]);$notifications->send($ticket->user_id,'ticket_reply','پاسخ جدید پشتیبانی','پشتیبانی به تیکت «'.$ticket->subject.'» پاسخ داد.','/profile/tickets/'.$ticket->id);return response()->json($message,201);}public function update(Request $r,SupportTicket $ticket){$data=$r->validate(['status'=>'sometimes|in:open,pending,answered,closed','priority'=>'sometimes|in:low,normal,high','department'=>'sometimes|in:support,orders,payment,returns']);$ticket->update($data);return $ticket->fresh();}}
